function fmtTime(value){if(!value)return"—";const date=new Date(value);return Number.isNaN(date.valueOf())?String(value):date.getUTCFullYear()<=1?"—":date.toLocaleString()}

function applyTheme(value){const theme=["auto","light","dark"].includes(value)?value:"auto";document.documentElement.dataset.theme=theme;try{localStorage.setItem("theme",theme)}catch{}for(const button of document.querySelectorAll(".theme-switch [data-theme]")){const active=button.dataset.theme===theme;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active))}}
