function selectView(requested,activate=true){const view=Object.prototype.hasOwnProperty.call(VIEWS,requested)?requested:"overview",meta=VIEWS[view],wanted=`#/${view}`;state.view=view;for(const button of document.querySelectorAll("[data-view]")){const active=button.dataset.view===view;button.classList.toggle("active",active);button.setAttribute("aria-current",active?"page":"false")}for(const section of document.querySelectorAll(".view"))section.classList.toggle("hidden",section.id!==`view-${view}`);el("page-title").textContent=meta.title;el("page-subtitle").textContent=meta.subtitle;document.title=`${meta.title} · MDD Sim Gateway`;if(location.hash!==wanted)history.replaceState(null,"",wanted);if(!activate)return;if(view==="system")loadSystemStatus();if(view==="devices")loadDevices();if(view==="settings"){if(!state.runtime)loadRuntime();loadLineCatalog();loadLineCandidates();loadProviderConfig();loadEgressConfig()}if(view==="imei"){loadLineCatalog();loadIMEIPool()}if(view==="notifications")loadNotifications();if(view==="diagnostics")loadDiagnostics();if(view==="calls"){refreshCallStatuses();loadCallHistory()}if(view==="messages"){refreshSelectedCellularMessages();loadAllowanceForSelectedLine(true)}else clearAllowancePoll();if(view==="esim")loadEUICCs()}

async function loadNotifications(){
  if(state.notificationsLoading)return;state.notificationsLoading=true;el("refresh-notifications").disabled=true;
  const [configResult,deliveryResult]=await Promise.allSettled([jsonRequest("/v1/notifications/config"),jsonRequest("/v1/notifications/deliveries")]);
  if(configResult.status==="fulfilled"){state.notificationConfig=configResult.value;renderNotificationConfig()}else{state.notificationConfig=null;showNotificationConfigResult(`通知配置读取失败：${configResult.reason.code||configResult.reason.message}`,true)}
  if(deliveryResult.status==="fulfilled"){state.notificationDeliveries=Array.isArray(deliveryResult.value.deliveries)?deliveryResult.value.deliveries:[];renderNotificationDeliveries()}else{state.notificationDeliveries=[];el("notification-deliveries").replaceChildren(errorCard(`投递记录读取失败：${deliveryResult.reason.code||deliveryResult.reason.message}`))}
  state.notificationsLoading=false;el("refresh-notifications").disabled=false;
}

async function loadNotificationDeliveries(){
  el("refresh-notification-deliveries").disabled=true;
  try{const payload=await jsonRequest("/v1/notifications/deliveries");state.notificationDeliveries=Array.isArray(payload.deliveries)?payload.deliveries:[];renderNotificationDeliveries()}
  catch(error){el("notification-deliveries").replaceChildren(errorCard(`投递记录读取失败：${error.code||error.message}`))}
  finally{el("refresh-notification-deliveries").disabled=false}
}

function renderNotificationConfig(){
  const config=state.notificationConfig;if(!config)return;
  el("notification-timezone").value=config.timezone||"Asia/Shanghai";
  for(const channel of ["webhook","telegram","pushplus"]){
    const view=config[channel]||{};el(`notification-${channel}-enabled`).checked=view.enabled===true;
    for(const input of document.querySelectorAll(`[data-notification-channel="${channel}"][data-notification-event]`))input.checked=view.events?.[input.dataset.notificationEvent]===true;
  }
  el("notification-webhook-format").value=config.webhook.format||"generic";el("notification-webhook-method").value=config.webhook.method||"POST";el("notification-webhook-body-mode").value=config.webhook.body_mode||"json";el("notification-webhook-tls-pin").value=config.webhook.tls_cert_sha256||"";
  setNotificationSecret("notification-webhook-url",config.webhook.url);setNotificationSecret("notification-webhook-headers",config.webhook.headers);setNotificationSecret("notification-webhook-template",config.webhook.payload_template);
  el("notification-telegram-proxy-mode").value=config.telegram.proxy_mode||"direct";el("notification-telegram-proxy-country").value=config.telegram.proxy_country||"";
  setNotificationSecret("notification-telegram-token",config.telegram.bot_token);setNotificationSecret("notification-telegram-chat",config.telegram.chat_id);setNotificationSecret("notification-telegram-proxy",config.telegram.proxy_url,"notification-telegram-proxy-url");
  el("notification-pushplus-template").value=config.pushplus.template||"html";el("notification-pushplus-channel").value=config.pushplus.channel||"wechat";
  setNotificationSecret("notification-pushplus-token",config.pushplus.token);setNotificationSecret("notification-pushplus-topic",config.pushplus.topic);
  syncNotificationControls();
}

function setNotificationSecret(prefix,view,inputID=prefix){const input=el(inputID),configured=view?.configured===true;input.value="";input.placeholder=configured?"已配置；留空保留现有值":"尚未配置";el(`${prefix}-state`).textContent=configured?"（已配置，不回显）":"（未配置）";const clear=el(`${prefix}-clear`);if(clear)clear.checked=false}
function notificationEvents(channel){const result={};for(const input of document.querySelectorAll(`[data-notification-channel="${channel}"][data-notification-event]`))result[input.dataset.notificationEvent]=input.checked;return result}
function applyNotificationSecret(target,key,inputID,clearID){const value=el(inputID).value;if(el(clearID).checked)target[key]="";else if(value!=="")target[key]=value}

function syncNotificationControls(){
  const config=state.notificationConfig,manual=el("notification-telegram-proxy-mode").value==="manual",country=el("notification-telegram-proxy-mode").value==="country";
  el("notification-telegram-proxy-url").disabled=!manual;el("notification-telegram-proxy-country").disabled=!country;
  const ready={
    webhook:config?.webhook?.enabled&&config.webhook.url?.configured,
    telegram:config?.telegram?.enabled&&config.telegram.bot_token?.configured&&config.telegram.chat_id?.configured,
    pushplus:config?.pushplus?.enabled&&config.pushplus.token?.configured,
  };
  for(const channel of ["webhook","telegram","pushplus"]){const button=el(`notification-test-${channel}`);if(!button.dataset.testing)button.disabled=!button.dataset.operationId&&!ready[channel]}
}

async function saveNotificationConfig(event){
  event.preventDefault();const current=state.notificationConfig;if(!current)return;
  const webhook={enabled:el("notification-webhook-enabled").checked,events:notificationEvents("webhook"),format:el("notification-webhook-format").value,method:el("notification-webhook-method").value,body_mode:el("notification-webhook-body-mode").value,tls_cert_sha256:el("notification-webhook-tls-pin").value.trim().toLowerCase()};
  applyNotificationSecret(webhook,"url","notification-webhook-url","notification-webhook-url-clear");applyNotificationSecret(webhook,"headers_json","notification-webhook-headers","notification-webhook-headers-clear");applyNotificationSecret(webhook,"payload_template","notification-webhook-template","notification-webhook-template-clear");
  const telegram={enabled:el("notification-telegram-enabled").checked,events:notificationEvents("telegram"),proxy_mode:el("notification-telegram-proxy-mode").value,proxy_country:el("notification-telegram-proxy-country").value.trim().toLowerCase()};
  applyNotificationSecret(telegram,"bot_token","notification-telegram-token","notification-telegram-token-clear");applyNotificationSecret(telegram,"chat_id","notification-telegram-chat","notification-telegram-chat-clear");applyNotificationSecret(telegram,"proxy_url","notification-telegram-proxy-url","notification-telegram-proxy-clear");
  const pushplus={enabled:el("notification-pushplus-enabled").checked,events:notificationEvents("pushplus"),template:el("notification-pushplus-template").value,channel:el("notification-pushplus-channel").value};
  applyNotificationSecret(pushplus,"token","notification-pushplus-token","notification-pushplus-token-clear");applyNotificationSecret(pushplus,"topic","notification-pushplus-topic","notification-pushplus-topic-clear");
  const newlyEnabled=(!current.webhook.enabled&&webhook.enabled)||(!current.telegram.enabled&&telegram.enabled)||(!current.pushplus.enabled&&pushplus.enabled),newGET=webhook.enabled&&webhook.method==="GET"&&(!current.webhook.enabled||current.webhook.method!=="GET");
  if(newlyEnabled&&!confirm("启用通知会把线路名称/ID、ICCID、MSISDN、短信来源/来电号码、短信正文、到期日期或主机告警信息和发生时间发送给所选第三方。继续保存？"))return;
  if(newGET&&!confirm("Webhook GET 会把通知字段放进 URL 查询，目标服务和中间代理可能记录完整号码与短信正文。确认仍要使用 GET？"))return;
  const button=el("save-notifications");button.disabled=true;showNotificationConfigResult("正在保存；旧 revision 的未发送投递会被取消，已写出的结果不会伪装成取消…");
  try{const updated=await jsonRequest("/v1/notifications/config",{method:"PUT",body:JSON.stringify({expected_revision:current.revision,timezone:el("notification-timezone").value.trim(),webhook,telegram,pushplus})});state.notificationConfig=updated;renderNotificationConfig();showNotificationConfigResult(`通知配置 revision ${updated.revision} 已保存；没有发送测试或历史事件。`);await loadNotificationDeliveries()}
  catch(error){showNotificationConfigResult(`保存失败：${error.code||error.message}`,true);if(error.status===412)await loadNotifications()}
  finally{button.disabled=false}
}

function showNotificationConfigResult(message,failed=false){const result=el("notification-config-result");result.classList.remove("hidden");result.textContent=message;result.style.color=failed?"var(--status-danger)":"var(--status-neutral)"}
function showNotificationTestResult(channel,message,failed=false){const result=el(`notification-test-${channel}-result`);result.classList.remove("hidden");result.textContent=message;result.style.color=failed?"var(--status-danger)":"var(--status-neutral)"}

async function testNotificationChannel(channel){
  const button=el(`notification-test-${channel}`),replay=button.dataset.operationId!==undefined;if(button.disabled||!confirm(replay?`重读同一 ${channel} 测试请求？\n\n将复用原 operation_id；不会创建第二次发送身份。`:`通过 ${channel} 发送一次真实测试通知？\n\n只发送一次；结果不明确时不会自动重发。`))return;
  const operation=button.dataset.operationId||operationID(`notification-test-${channel}`);setNotificationTestOperation(channel,operation);
  button.dataset.testing="true";button.disabled=true;showNotificationTestResult(channel,"正在创建持久幂等测试；不会自动重试结果不明的请求…");
  try{const payload=await jsonRequest(`/v1/notifications/tests/${encodeURIComponent(channel)}`,{method:"POST",body:JSON.stringify({operation_id:operation})});const delivery=payload.delivery;showNotificationTestResult(channel,`测试已进入 ${delivery.state}；正在读取同一 delivery 的最终结果…`);if(await pollNotificationTest(channel,delivery.delivery_id))setNotificationTestOperation(channel,"")}
  catch(error){showNotificationTestResult(channel,`测试请求结果未确认：${error.code||error.message}。再次点击只会复用同一 operation_id，不会生成第二次发送身份。`,true)}
  finally{delete button.dataset.testing;syncNotificationControls()}
}

async function pollNotificationTest(channel,deliveryID){
  for(let attempt=0;attempt<12;attempt++){
    await new Promise(resolve=>setTimeout(resolve,1000));
    const payload=await jsonRequest("/v1/notifications/deliveries");state.notificationDeliveries=Array.isArray(payload.deliveries)?payload.deliveries:[];renderNotificationDeliveries();const delivery=state.notificationDeliveries.find(item=>item.delivery_id===deliveryID);
    if(!delivery)throw new Error("测试 delivery 不在持久记录中");
    if(["delivered","failed","uncertain","canceled"].includes(delivery.state)){const failed=delivery.state!=="delivered";showNotificationTestResult(channel,`${delivery.state.toUpperCase()} · ${delivery.code||"无状态码"} · attempts ${delivery.attempts}`,failed);return delivery.state!=="uncertain"}
  }
  showNotificationTestResult(channel,"测试仍在处理；再次点击只会复用同一 operation_id。也可刷新投递记录继续查看。",true);return false
}

function renderNotificationDeliveries(){
  restoreNotificationTestOperations();const root=el("notification-deliveries");root.replaceChildren();const deliveries=state.notificationDeliveries||[];if(!deliveries.length){root.append(empty("尚无通知投递记录"));return}
  for(const delivery of deliveries){const card=document.createElement("article"),head=document.createElement("div"),title=document.createElement("div"),heading=document.createElement("h3"),detail=document.createElement("div"),badge=document.createElement("span"),meta=document.createElement("div");card.className="card";head.className="card-head";heading.textContent=`${notificationChannelLabel(delivery.channel)} · ${notificationEventLabel(delivery.event_type)}`;detail.className="muted";detail.textContent=delivery.kind==="test"?"显式渠道测试":`线路 ${delivery.line_id||"—"}`;title.append(heading,detail);badge.className=`badge ${notificationDeliveryClass(delivery.state)}`;badge.textContent=delivery.state;head.append(title,badge);meta.className="notification-delivery-meta muted";for(const value of[`code ${delivery.code||"—"}`,`attempts ${delivery.attempts}`,delivery.http_status?`HTTP ${delivery.http_status}`:"",`更新 ${fmtTime(delivery.updated_at)}`]){if(!value)continue;const span=document.createElement("span");span.textContent=value;meta.append(span)}card.append(head,meta);root.append(card)}
}

function setNotificationTestOperation(channel,operationID){const button=el(`notification-test-${channel}`);if(operationID){button.dataset.operationId=operationID;button.textContent="重读同一测试";button.disabled=false}else{delete button.dataset.operationId;button.textContent="发送一次测试";syncNotificationControls()}}
function restoreNotificationTestOperations(){for(const channel of ["webhook","telegram","pushplus"]){const delivery=(state.notificationDeliveries||[]).find(item=>item.kind==="test"&&item.channel===channel&&["pending","sending","uncertain"].includes(item.state)&&item.operation_id);if(delivery)setNotificationTestOperation(channel,delivery.operation_id)}}

function notificationChannelLabel(value){return({webhook:"Webhook",telegram:"Telegram",pushplus:"PushPlus"})[value]||value}
function notificationEventLabel(value){return({incoming_sms:"实时短信",incoming_call:"呼入电话",host_alert:"主机告警",activation_reminder:"到期提醒",test:"渠道测试"})[value]||value}
function notificationDeliveryClass(value){return value==="delivered"?"good":value==="pending"||value==="sending"?"warn":value==="canceled"?"neutral":"bad"}

async function clearNotificationDeliveries(){if(!confirm("清除普通事件的已完成投递记录？\n\n测试记录会继续保留稳定幂等身份；pending/sending 记录不会删除。"))return;const button=el("clear-notification-deliveries");button.disabled=true;try{const result=await jsonRequest("/v1/notifications/deliveries",{method:"DELETE",body:"{}"});showNotice(`已清除 ${result.deleted||0} 条普通终态通知记录。`);await loadNotificationDeliveries()}catch(error){showNotice(`通知记录清理失败：${error.code||error.message}`)}finally{button.disabled=false}}

async function loadEUICCs(){if(state.euiccLoading)return;state.euiccLoading=true;const button=el("refresh-euiccs");button.disabled=true;try{const payload=await jsonRequest("/v1/euiccs");state.euiccs=Array.isArray(payload.euiccs)?payload.euiccs:[];renderEUICCs()}catch(error){state.euiccs=null;el("euiccs").replaceChildren(errorCard(`eUICC 清单读取失败：${error.code||error.message}`))}finally{state.euiccLoading=false;button.disabled=false}}

function renderEUICCs(){
  const root=el("euiccs");root.replaceChildren();const entries=state.euiccs||[];
  if(!entries.length){root.append(empty("当前没有已识别的 eUICC"));return}
  for(const entry of entries){
    const card=document.createElement("article");card.className="card";card.dataset.eid=entry.euicc.eid;
    const head=document.createElement("div");head.className="card-head";
    const title=document.createElement("div"),heading=document.createElement("h3"),meta=document.createElement("div"),capabilities=document.createElement("div");
    heading.textContent=`${entry.slot_label?`${entry.slot_label} · `:""}EID ${entry.euicc.eid}`;meta.className="muted";meta.textContent=`${entry.agent_id} · ${entry.reader_name}${entry.slot_id?` · ${entry.slot_id}`:""} · 插入代际 ${entry.session_generation}`;
    capabilities.className="badges";capabilities.append(euiccCapability(entry.euicc.profile_management,"Profile 管理"),euiccCapability(entry.euicc.profile_download,"Profile 下载"),euiccCapability(entry.euicc.profile_discovery,"SM-DS 查询"),euiccCapability(entry.euicc.notification_inventory,"卡内通知"),euiccCapability(entry.euicc.notification_delivery,"通知发送"),euiccCapability(entry.euicc.notification_removal,"确认后移除"));
    title.append(heading,meta);head.append(title,capabilities);card.append(head);
    const toolbar=document.createElement("div");toolbar.className="toolbar";
    const download=actionButton("下载 Profile",()=>showEUICCDownloadForm(entry,card));download.disabled=!entry.euicc.profile_download;const discovery=actionButton("查询待下载 Profile",()=>showEUICCDiscoveryForm(entry,card));discovery.className="secondary";discovery.disabled=!entry.euicc.profile_discovery;const notifications=actionButton("查看卡内通知",()=>loadEUICCNotifications(entry,card,notifications));notifications.className="secondary";notifications.dataset.notificationInventoryButton="";notifications.disabled=!entry.euicc.notification_inventory;toolbar.append(download,discovery,notifications);card.append(toolbar);
    const profiles=document.createElement("div");profiles.className="readers";
    if(!entry.euicc.profiles_available){profiles.append(empty("Profile 清单当前不可用"))}
    else if(!(entry.euicc.profiles||[]).length){profiles.append(empty("空白 eUICC：没有 Profile"))}
    else{for(const profile of entry.euicc.profiles){profiles.append(euiccProfileRow(entry,profile))}}
    card.append(profiles);
    const result=document.createElement("div");result.className="result hidden";result.dataset.euiccResult="";card.append(result);
    const remembered=state.euiccDownloads.get(entry.euicc.eid),reported=entry.euicc.download;
    if(reported&&(!remembered||reported.operation_id===remembered.operation_id)){state.euiccDownloads.set(entry.euicc.eid,reported);saveEUICCDownloads()}
    renderEUICCDownloadStatus(card,entry);
    root.append(card)
  }
}

function euiccCapability(enabled,label){const badge=document.createElement("span");badge.className=`badge ${enabled?"good":"neutral"}`;badge.textContent=enabled?label:`${label}只读`;return badge}

function euiccProfileRow(entry,profile){const row=document.createElement("div");row.className="reader";const head=document.createElement("div");head.className="card-head";const identity=document.createElement("div"),name=document.createElement("strong"),meta=document.createElement("div"),stateBadge=document.createElement("span");name.textContent=profile.nickname||profile.profile_name||profile.service_provider_name||profile.iccid;meta.className="muted";meta.textContent=[profile.iccid,profile.service_provider_name,profile.profile_name].filter((value,index,array)=>value&&array.indexOf(value)===index).join(" · ");stateBadge.className=`badge ${profile.state==="enabled"?"good":"neutral"}`;stateBadge.textContent=profile.state==="enabled"?"已启用":"已停用";identity.append(name,meta);head.append(identity,stateBadge);row.append(head);const action=profile.state==="enabled"?"disable":"enable",button=document.createElement("button");button.className=action==="disable"?"secondary":"";button.textContent=action==="disable"?"停用 Profile":"启用 Profile";button.disabled=!entry.euicc.profile_management;button.addEventListener("click",()=>changeEUICCProfile(entry,profile,action,button));const rename=document.createElement("button");rename.className="secondary";rename.textContent="修改昵称";rename.disabled=!entry.euicc.profile_management;rename.addEventListener("click",()=>renameEUICCProfile(entry,profile,rename));const toolbar=document.createElement("div");toolbar.className="toolbar";toolbar.append(button,rename);row.append(toolbar);return row}

async function changeEUICCProfile(entry,profile,action,button){const verb=action==="enable"?"启用":"停用",result=button.closest(".card").querySelector("[data-euicc-result]");if(!confirm(`${verb} Profile ${profile.iccid}？\n\n操作只会发送到当前 EID、ICCID 和插入代际完全匹配的 Agent。`))return;button.disabled=true;result.classList.remove("hidden");result.style.color="var(--status-neutral)";result.textContent=`正在${verb}；等待 Agent 返回明确提交结果…`;try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/profiles/${encodeURIComponent(profile.iccid)}/${action}`,{method:"POST",body:JSON.stringify({operation_id:operationID(`ui-euicc-${action}`),expected_state:profile.state})});if(payload.outcome==="already_applied"){result.textContent=`当前状态已经是${verb}后的目标状态；没有重复写卡。`}else if(payload.outcome==="refresh_pending"){result.textContent=`写卡命令已提交；Agent 正在重读该卡片。请刷新确认新状态。`}else{result.style.color="var(--status-warning)";result.textContent="写卡结果不确定；Agent 正在重读该卡片。不要更换目标后重试，请先刷新当前状态。"}setTimeout(loadEUICCs,1500)}catch(error){result.style.color="var(--status-danger)";result.textContent=`${verb}失败：${error.code||error.message}`;button.disabled=false}}

function openEUICCNicknameDialog(profile){return new Promise(resolve=>{const backdrop=document.createElement("div"),dialog=document.createElement("form"),heading=document.createElement("h3"),identity=document.createElement("div"),label=document.createElement("label"),input=document.createElement("input"),hint=document.createElement("span"),error=document.createElement("div"),actions=document.createElement("div"),save=document.createElement("button"),cancel=document.createElement("button");backdrop.className="euicc-modal-backdrop";dialog.className="panel euicc-modal";dialog.setAttribute("role","dialog");dialog.setAttribute("aria-modal","true");heading.textContent="修改 Profile 昵称";identity.className="muted";identity.textContent=profile.iccid;input.value=profile.nickname||"";input.placeholder="留空可清除昵称";hint.className="muted";hint.textContent="最多 64 个 UTF-8 字节；保存前仍会核对卡片上的旧昵称。";label.append(document.createTextNode("昵称"),input,hint);error.className="error";actions.className="toolbar";save.type="submit";save.textContent="保存";cancel.type="button";cancel.className="secondary";cancel.textContent="取消";actions.append(save,cancel);dialog.append(heading,identity,label,error,actions);backdrop.append(dialog);document.body.append(backdrop);let settled=false;const finish=value=>{if(settled)return;settled=true;backdrop.remove();resolve(value)};cancel.addEventListener("click",()=>finish(null));backdrop.addEventListener("click",event=>{if(event.target===backdrop)finish(null)});dialog.addEventListener("keydown",event=>{if(event.key==="Escape"){event.preventDefault();finish(null)}});dialog.addEventListener("submit",event=>{event.preventDefault();const nickname=input.value.trim();if(new TextEncoder().encode(nickname).length>64){error.textContent="Profile 昵称不能超过 64 个 UTF-8 字节";return}finish(nickname)});input.focus()})}

async function renameEUICCProfile(entry,profile,button){const nickname=await openEUICCNicknameDialog(profile);if(nickname===null)return;const result=button.closest(".card").querySelector("[data-euicc-result]");button.disabled=true;result.classList.remove("hidden");result.style.color="var(--status-neutral)";result.textContent="正在修改昵称；等待 Agent 返回明确提交结果…";try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/profiles/${encodeURIComponent(profile.iccid)}/nickname`,{method:"POST",body:JSON.stringify({operation_id:operationID("ui-euicc-nickname"),nickname,expected_nickname:profile.nickname||""})});if(payload.outcome==="already_applied"){result.textContent="卡片上的昵称已经相同；没有重复写卡。"}else if(payload.outcome==="refresh_pending"){result.textContent="昵称命令已提交；Agent 正在重读该卡片。"}else{result.style.color="var(--status-warning)";result.textContent="昵称写入结果不确定；请先刷新卡片状态，不要直接重试。"}setTimeout(loadEUICCs,1500)}catch(error){result.style.color="var(--status-danger)";result.textContent=`修改昵称失败：${error.code||error.message}`;button.disabled=false}}

function showEUICCDiscoveryForm(entry,card){const prior=card.querySelector("[data-euicc-discovery-form]");if(prior){prior.remove();return}const form=document.createElement("form"),smds=document.createElement("input"),imei=document.createElement("input"),hint=document.createElement("div"),actions=document.createElement("div"),submit=document.createElement("button"),cancel=document.createElement("button");form.dataset.euiccDiscoveryForm="";form.className="panel";smds.placeholder="SM-DS（留空使用 lpa.ds.gsma.com）";smds.autocomplete="off";imei.placeholder="IMEI（可选，15 位数字）";imei.inputMode="numeric";imei.maxLength=15;hint.className="muted";hint.textContent="仅查询该 EID 的待处理事件；不会下载、写卡、保存参数或自动重试。最长等待 120 秒。";submit.type="submit";submit.textContent="开始查询";cancel.type="button";cancel.className="secondary";cancel.textContent="取消";actions.className="toolbar";actions.append(submit,cancel);form.append(smds,imei,hint,actions);card.querySelector("[data-euicc-result]").before(form);cancel.addEventListener("click",()=>form.remove());form.addEventListener("submit",async event=>{event.preventDefault();const identity=imei.value.trim();if(identity&&!/^\d{15}$/.test(identity)){showNotice("IMEI 必须为空或 15 位数字");return}submit.disabled=true;cancel.disabled=true;const result=card.querySelector("[data-euicc-result]");result.classList.remove("hidden");result.style.color="var(--status-neutral)";result.textContent="正在通过 Agent 和当前 eUICC 查询 SM-DS…";try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/discovery`,{method:"POST",body:JSON.stringify({operation_id:operationID("ui-euicc-discovery"),smds:smds.value.trim(),imei:identity})});result.replaceChildren();const title=document.createElement("strong");title.textContent=`SM-DS ${payload.smds}：${payload.entries?.length||0} 个待处理事件`;result.append(title);for(const item of payload.entries||[]){const row=document.createElement("div");row.className="muted";row.textContent=`${item.rsp_server_address} · Event ${item.event_id}`;result.append(row)}form.remove()}catch(error){result.style.color="var(--status-danger)";result.textContent=`SM-DS 查询失败：${error.code||error.message}`;submit.disabled=false;cancel.disabled=false}})}

async function loadEUICCNotifications(entry,card,button){const result=card.querySelector("[data-euicc-result]");button.disabled=true;result.classList.remove("hidden");result.style.color="var(--status-neutral)";result.textContent="正在读取当前 eUICC 的卡内通知…";try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/notifications`);const entries=payload.entries||[];result.replaceChildren();const title=document.createElement("strong");title.textContent=`卡内通知：${entries.length} 条`;result.append(title);for(const item of entries){const row=document.createElement("div"),text=document.createElement("span"),send=document.createElement("button");row.className="toolbar";text.className="muted";text.textContent=`#${item.sequence_number} · ${item.event}${item.iccid?` · ${item.iccid}`:""} · ${item.address}`;send.className="secondary";send.textContent="发送并确认移除";send.disabled=!entry.euicc.notification_delivery;send.addEventListener("click",()=>deliverEUICCNotification(entry,item,card,send));row.append(text,send);result.append(row)}}catch(error){result.style.color="var(--status-danger)";result.textContent=`卡内通知读取失败：${error.code||error.message}`}finally{button.disabled=false}}

async function deliverEUICCNotification(entry,item,card,button){if(!confirm(`发送卡内通知 #${item.sequence_number} 到 ${item.address}？\n\n仅在运营商服务器明确确认后才会从卡内移除；网络结果不确定时不会自动重发。`))return;const result=card.querySelector("[data-euicc-result]");button.disabled=true;result.style.color="var(--status-neutral)";result.textContent=`正在发送通知 #${item.sequence_number}；不会自动重试…`;try{await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/notifications/${encodeURIComponent(item.sequence_number)}/deliver`,{method:"POST",body:JSON.stringify({confirmed:true,event:item.event,iccid:item.iccid||"",address:item.address})});result.textContent=`通知 #${item.sequence_number} 已获运营商服务器确认并从卡内移除。`;const inventory=card.querySelector("[data-notification-inventory-button]");if(inventory)await loadEUICCNotifications(entry,card,inventory)}catch(error){result.style.color="var(--status-danger)";if(error.code==="euicc_notification_delivery_outcome_unknown"){result.textContent="发送结果不确定；系统没有自动重发。请先重新查看卡内通知，再决定是否操作。"}else if(error.code==="euicc_notification_acknowledged_not_removed"){showAcknowledgedNotificationRemoval(entry,item,card,result)}else{result.textContent=`通知发送失败：${error.code||error.message}`;button.disabled=false}}}

function showAcknowledgedNotificationRemoval(entry,item,card,result){result.replaceChildren();const text=document.createElement("span"),remove=document.createElement("button");text.textContent="运营商服务器已确认，但卡内通知未能移除。不要重发。";remove.className="secondary";remove.textContent="仅移除已确认记录";remove.disabled=!entry.euicc.notification_removal;remove.addEventListener("click",()=>removeAcknowledgedEUICCNotification(entry,item,card,remove));result.append(text,remove)}

async function removeAcknowledgedEUICCNotification(entry,item,card,button){if(!confirm(`仅从卡内移除已确认的通知 #${item.sequence_number}？\n\n该操作不会再次发送通知；只应用于运营商服务器已经明确确认的本次结果。`))return;button.disabled=true;const result=card.querySelector("[data-euicc-result]");result.style.color="var(--status-neutral)";result.textContent=`正在仅移除已确认通知 #${item.sequence_number}…`;try{await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/notifications/${encodeURIComponent(item.sequence_number)}/remove`,{method:"POST",body:JSON.stringify({confirmed:true,receiver_acknowledged:true,event:item.event,iccid:item.iccid||"",address:item.address})});result.textContent=`已从卡内移除通知 #${item.sequence_number}；没有再次发送。`;const inventory=card.querySelector("[data-notification-inventory-button]");if(inventory)await loadEUICCNotifications(entry,card,inventory)}catch(error){result.style.color="var(--status-danger)";result.textContent=error.code==="euicc_notification_removal_outcome_unknown"?"卡内移除结果不确定；请重新查看通知清单，不要重复发送。":`卡内移除失败：${error.code||error.message}`;button.disabled=false}}

function parseEUICCActivationCode(raw){let value=String(raw||"").trim();if(/^LPA:/i.test(value))value=value.slice(4);const parts=value.split("$");if(parts.length<3||parts[0]!=="1"||!parts[1])return null;return{value:`LPA:${value}`,smdp:parts[1],matching_id:parts[2]}}

async function decodeEUICCQRImage(file){
  if(!file||!String(file.type||"").startsWith("image/"))throw new Error("qr_not_image");
  if(file.size>16*1024*1024)throw new Error("qr_image_too_large");
  const {default:decodeQR}=await import("/assets/qr/decode.js"),bitmap=await createImageBitmap(file);
  try{
    if(bitmap.width>20000||bitmap.height>20000)throw new Error("qr_image_too_large");
    const attempted=new Set();
    for(const maximum of [1500,800,3000]){
      const scale=Math.min(1,maximum/Math.max(bitmap.width,bitmap.height)),width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale)),key=`${width}x${height}`;
      if(attempted.has(key))continue;attempted.add(key);
      const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;
      const context=canvas.getContext("2d",{willReadFrequently:true});if(!context)throw new Error("qr_canvas_unavailable");
      context.drawImage(bitmap,0,0,width,height);const pixels=context.getImageData(0,0,width,height);
      try{const decoded=decodeQR({data:pixels.data,width,height});if(String(decoded||"").trim())return String(decoded).trim()}catch{}
      if(scale===1)break;
    }
    return"";
  }finally{bitmap.close?.()}
}

function showEUICCDownloadForm(entry,card){
  const existing=card.querySelector("[data-download-form]");if(existing){existing.remove();return}
  const form=document.createElement("form");form.dataset.downloadForm="";form.className="line-config-form";
  const fieldset=document.createElement("fieldset"),legend=document.createElement("legend");legend.textContent="下载到当前 eUICC";fieldset.append(legend);
  const grid=document.createElement("div");grid.className="form-grid";
  const activation=document.createElement("textarea");activation.rows=3;activation.maxLength=2048;activation.placeholder="LPA:1$smdp.example.com$MATCHING-ID";
  const smdp=document.createElement("input");smdp.maxLength=512;smdp.placeholder="smdp.example.com（与 Activation code 二选一）";
  const matching=document.createElement("input");matching.maxLength=1024;matching.placeholder="Matching ID（手动模式可选）";
  const confirmation=document.createElement("input");confirmation.type="password";confirmation.maxLength=128;confirmation.autocomplete="off";
  const imei=document.createElement("input");imei.inputMode="numeric";imei.pattern="[0-9]{15}";imei.maxLength=15;imei.required=true;imei.value=defaultEUICCIMEI(entry);
  grid.append(labelField("Activation code",activation,true),labelField("SM-DP+ 地址",smdp),labelField("Matching ID",matching),labelField("Confirmation code（可选）",confirmation),labelField("IMEI（15 位）",imei));fieldset.append(grid);form.append(fieldset);
  const note=document.createElement("p");note.className="muted";note.textContent="下载码可能只能使用一次。MDD 不会记录明文，也不会在断线或结果不确定时自动重试。";form.append(note);
  const qrControls=document.createElement("div"),fileInput=document.createElement("input"),qrButton=document.createElement("button"),qrHint=document.createElement("span");qrControls.className="toolbar";fileInput.type="file";fileInput.accept="image/*";fileInput.hidden=true;qrButton.type="button";qrButton.className="secondary";qrButton.textContent="上传二维码图片";qrHint.className="muted";qrHint.textContent="也可把二维码截图粘贴或拖入当前表单；图片只在浏览器内解析";qrControls.append(fileInput,qrButton,qrHint);form.append(qrControls);
  const controls=document.createElement("div");controls.className="toolbar";const submit=document.createElement("button"),cancel=document.createElement("button");submit.type="submit";submit.textContent="确认并开始";cancel.type="button";cancel.className="secondary";cancel.textContent="取消";cancel.addEventListener("click",()=>form.remove());controls.append(submit,cancel);form.append(controls);
  const error=document.createElement("div");error.className="result hidden";form.append(error);
  let qrBusy=false;
  const showQRFailure=message=>{error.classList.remove("hidden");error.style.color="var(--status-danger)";error.textContent=message};
  const readQR=async file=>{if(!file||qrBusy)return;qrBusy=true;qrButton.disabled=true;qrButton.textContent="正在识别二维码…";error.classList.add("hidden");try{const text=await decodeEUICCQRImage(file);if(!text){showQRFailure("未在图片中找到二维码");return}const parsed=parseEUICCActivationCode(text);if(!parsed){showQRFailure("二维码内容不是 eSIM 激活码");return}activation.value=parsed.value;smdp.value="";matching.value="";error.classList.remove("hidden");error.style.color="var(--status-success)";error.textContent="已识别 eSIM 激活码；内容仅保留在当前表单中"}catch(problem){showQRFailure(problem.message==="qr_image_too_large"?"二维码图片过大（最大 16 MiB、20000 像素边长）":"无法读取该二维码图片")}finally{qrBusy=false;qrButton.disabled=false;qrButton.textContent="上传二维码图片"}};
  qrButton.addEventListener("click",()=>fileInput.click());fileInput.addEventListener("change",()=>{readQR(fileInput.files?.[0]);fileInput.value=""});
  form.addEventListener("paste",event=>{const item=Array.from(event.clipboardData?.items||[]).find(candidate=>String(candidate.type||"").startsWith("image/"));if(item){event.preventDefault();readQR(item.getAsFile())}});
  form.addEventListener("dragover",event=>event.preventDefault());
  form.addEventListener("drop",event=>{const file=Array.from(event.dataTransfer?.files||[]).find(candidate=>String(candidate.type||"").startsWith("image/"));if(file){event.preventDefault();readQR(file)}});
  form.addEventListener("submit",async event=>{
    event.preventDefault();error.classList.add("hidden");
    if(!form.reportValidity())return;
    if(!confirm(`确认把一个新 Profile 下载到 EID ${entry.euicc.eid}？\n\n下载码不会自动重试；如果结果不确定，请先查询状态。`))return;
    submit.disabled=true;cancel.disabled=true;
    let code=activation.value.trim(),server=smdp.value.trim(),matchingID=matching.value.trim();
    if((code?1:0)+(server?1:0)!==1){error.classList.remove("hidden");error.style.color="var(--status-danger)";error.textContent="请填写 Activation code，或填写 SM-DP+ 地址（二选一）";return}
    if(server){if(server.includes("$")||matchingID.includes("$")){error.classList.remove("hidden");error.style.color="var(--status-danger)";error.textContent="SM-DP+ 地址或 Matching ID 不能包含 $";return}code=`LPA:1$${server}$${matchingID}`}
    const operation=operationID("ui-euicc-download"),body={operation_id:operation,activation_code:code,confirmation_code:confirmation.value.trim(),imei:imei.value.trim()};
    try{
      await stopEUICCVoWiFiLines(entry);
      const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(entry.euicc.eid)}/downloads`,{method:"POST",body:JSON.stringify(body)});
      activation.value="";smdp.value="";matching.value="";confirmation.value="";state.euiccDownloads.set(entry.euicc.eid,{operation_id:operation,job:payload.job});saveEUICCDownloads();form.remove();renderEUICCs();pollEUICCDownload(entry.euicc.eid,operation)
    }catch(problem){error.classList.remove("hidden");error.style.color="var(--status-danger)";error.textContent=`下载未开始：${problem.code||problem.message}`;submit.disabled=false;cancel.disabled=false}
  });
  card.insertBefore(form,card.querySelector(".readers"))
}

function labelField(text,input,wide=false){const label=document.createElement("label");if(wide)label.className="form-wide";label.append(document.createTextNode(text),input);return label}

function defaultEUICCIMEI(entry){
  const ids=new Set((entry.euicc.profiles||[]).map(profile=>profile.iccid));
  const line=(state.lineCatalog?.lines||[]).find(candidate=>ids.has(candidate.card_id)&&/^\d{15}$/.test(candidate.sim?.imei||""));
  return line?.sim?.imei||""
}

async function stopEUICCVoWiFiLines(entry){
  const ids=new Set((entry.euicc.profiles||[]).map(profile=>profile.iccid));
  const lines=(state.lineCatalog?.lines||[]).filter(line=>line.enabled&&ids.has(line.card_id));
  for(const line of lines){
    const status=await jsonRequest(`/v1/lines/${encodeURIComponent(line.id)}/vowifi/status`);
    if(status.active_call)throw new Error(`线路 ${line.name||line.id} 正在通话，不能开始下载`);
    if(status.runtime?.condition==="stopped")continue;
    if(!confirm(`线路 ${line.name||line.id} 当前为 ${status.runtime?.condition||"unknown"}。下载需要独占卡片，是否先停止该线路？`))throw new Error("已取消下载");
    const stopped=await jsonRequest(`/v1/lines/${encodeURIComponent(line.id)}/vowifi/runtime/stop`,{method:"POST",body:JSON.stringify({operation_id:operationID("ui-euicc-stop")})});
    if(stopped.status?.runtime?.condition!=="stopped")throw new Error(`线路 ${line.name||line.id} 未确认停止`)
  }
}

function renderEUICCDownloadStatus(card,entry){
  const fact=state.euiccDownloads.get(entry.euicc.eid);if(!fact?.job)return;
  const status=document.createElement("div");status.className="result";status.dataset.downloadStatus="";
  const job=fact.job,detail=[`下载 ${job.state}`,`阶段 ${job.stage}`,job.code,job.metadata?.profile_name||job.metadata?.service_provider_name,job.metadata?.iccid,fact.status_error&&`状态暂不可读：${fact.status_error}`].filter(Boolean).join(" · ");status.textContent=detail;
  if(["failed","uncertain"].includes(job.state))status.style.color="var(--status-danger)";else if(job.state==="completed")status.style.color="var(--status-success)";
  if(["queued","running","cancelling"].includes(job.state)){
    const cancel=document.createElement("button");cancel.type="button";cancel.className="secondary";cancel.textContent=job.state==="cancelling"?"正在取消":"取消下载";cancel.disabled=job.state==="cancelling";cancel.addEventListener("click",()=>cancelEUICCDownload(entry.euicc.eid,fact.operation_id,cancel));status.append(document.createTextNode(" "),cancel);pollEUICCDownload(entry.euicc.eid,fact.operation_id)
  }
  card.append(status)
}

async function pollEUICCDownload(eid,operation){
  const current=state.euiccDownloads.get(eid);if(!current||current.operation_id!==operation||current.polling)return;current.polling=true;
  try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(eid)}/downloads/${encodeURIComponent(operation)}`);current.job=payload.job;delete current.status_error;saveEUICCDownloads();renderEUICCs();if(["queued","running","cancelling"].includes(payload.job?.state))setTimeout(()=>pollEUICCDownload(eid,operation),1500);else if(payload.job?.state==="completed")setTimeout(loadEUICCs,1000)}
  catch(problem){current.status_error=problem.code||"status_unavailable";saveEUICCDownloads();renderEUICCs();setTimeout(()=>pollEUICCDownload(eid,operation),3000)}
  finally{current.polling=false}
}

async function cancelEUICCDownload(eid,operation,button){button.disabled=true;try{const payload=await jsonRequest(`/v1/euiccs/${encodeURIComponent(eid)}/downloads/${encodeURIComponent(operation)}/cancel`,{method:"POST",body:"{}"});state.euiccDownloads.set(eid,{operation_id:operation,job:payload.job});saveEUICCDownloads();renderEUICCs()}catch(problem){button.disabled=false;showNotice(`取消下载失败：${problem.code||problem.message}`)}}

function saveEUICCDownloads(){const value=[];for(const [eid,fact] of state.euiccDownloads){if(fact?.operation_id)value.push({eid,operation_id:fact.operation_id,job:fact.job})}localStorage.setItem("mdd-euicc-downloads",JSON.stringify(value))}
function restoreEUICCDownloads(){try{const value=JSON.parse(localStorage.getItem("mdd-euicc-downloads")||"[]");for(const fact of value){if(/^\d{32}$/.test(fact.eid)&&fact.operation_id)state.euiccDownloads.set(fact.eid,{operation_id:fact.operation_id,job:fact.job})}}catch{localStorage.removeItem("mdd-euicc-downloads")}}

