function formatBytes(value){const bytes=Number(value);if(!Number.isFinite(bytes)||bytes<0)return"—";const units=["B","KiB","MiB","GiB","TiB"];let index=0,current=bytes;while(current>=1024&&index<units.length-1){current/=1024;index++}return`${current>=100?Math.round(current):Number(current.toFixed(1))} ${units[index]}`}
function formatDuration(value){let seconds=Number(value);if(!Number.isFinite(seconds)||seconds<0)return"—";seconds=Math.floor(seconds);const days=Math.floor(seconds/86400);seconds%=86400;const hours=Math.floor(seconds/3600);seconds%=3600;const minutes=Math.floor(seconds/60);return[days&&`${days}d`,hours&&`${hours}h`,minutes&&`${minutes}m`].filter(Boolean).join(" ")||"<1m"}
async function loadLineCandidates(){if(state.lineCandidatesLoading)return;state.lineCandidatesLoading=true;const button=el("refresh-line-candidates");button.disabled=true;try{state.lineCandidates=await jsonRequest("/v1/line-candidates");renderLineCandidates()}catch(error){state.lineCandidates=null;el("line-candidates").replaceChildren(errorCard(`在线 SIM 读取失败：${error.code||error.message}`))}finally{state.lineCandidatesLoading=false;button.disabled=false}}
function renderLineCandidates(){const root=el("line-candidates"),candidates=state.lineCandidates?.candidates||[];root.replaceChildren();if(!candidates.length){root.append(empty("当前没有 30 秒内确认的 SIM 卡附件"));return}for(const candidate of candidates){const card=document.createElement("article"),head=document.createElement("div"),title=document.createElement("div"),heading=document.createElement("h3"),meta=document.createElement("div"),badges=document.createElement("div"),status=document.createElement("span");card.className="card";head.className="card-head";heading.textContent=candidate.kind==="modem"?"蜂窝 Modem SIM":"远程 PC/SC SIM";meta.className="muted";meta.textContent=[`ICCID ${candidate.card_id}`,`Agent ${candidate.agent_id}`,candidate.equipment_id&&`设备 ${candidate.equipment_id}`,candidate.reader_name&&`读卡器 ${candidate.reader_name}`,`插入代际 ${(candidate.session_generation||"").slice(0,12)}`].filter(Boolean).join(" · ");title.append(heading,meta);badges.className="badges";status.className=`badge ${candidate.can_claim?"warn":candidate.condition==="configured"?"good":"bad"}`;status.textContent=lineCandidateCondition(candidate);badges.append(status);if(candidate.raw){const raw=document.createElement("span");raw.className="badge neutral";raw.textContent=candidate.raw.available?"透传可用":"透传隔离未证明";badges.append(raw)}head.append(title,badges);card.append(head);const observed=candidate.observed||{};card.append(keyValueCard("当前权威身份",[["IMSI",observed.imsi||"未读取"],["MCC",observed.mcc||"未读取"],["MNC",observed.mnc||"不猜测，请确认"],["IMEI",observed.imei||"未读取"],["MSISDN",observed.msisdn||"未唯一确认"],["SMSC",observed.smsc||"未读取"]]));if(candidate.configured_line_id){const note=document.createElement("div");note.className="muted";note.textContent=`该 ICCID 已属于线路 ${candidate.configured_line_id}，不会重复建立。`;card.append(note)}else if(candidate.can_claim){const form=document.createElement("div"),label=document.createElement("label"),name=document.createElement("input"),button=document.createElement("button");form.className="toolbar";label.textContent="草稿名称";name.maxLength=256;name.value=candidate.kind==="modem"?"Modem SIM":"远程 SIM";label.append(name);button.type="button";button.textContent="创建禁用草稿";button.addEventListener("click",()=>claimLineCandidate(candidate,name.value,button));form.append(label,button);card.append(form)}else{const note=document.createElement("div");note.className="error";note.textContent=candidate.condition==="ambiguous_card"?"同一 ICCID 当前出现在多个附件上；先排除重复上报，系统不会猜测目标。":"当前卡片不能建立线路草稿。";card.append(note)}root.append(card)}}
