async function claimLineCandidate(candidate,name,button){const snapshot=state.lineCandidates;if(!snapshot||!candidate.can_claim)return;const target=[`ICCID ${candidate.card_id}`,candidate.equipment_id&&`设备 ${candidate.equipment_id}`,`Agent ${candidate.agent_id}`].filter(Boolean).join("\n");if(!confirm(`只为以下当前附件创建一个禁用草稿：\n${target}\n\n不会启动、注册、拨号、发短信或应用 Provider。`))return;button.disabled=true;showLineCandidateResult("正在重新核对 Agent、设备与插卡代际…");try{const result=await jsonRequest(`/v1/line-candidates/${encodeURIComponent(candidate.candidate_id)}/claim`,{method:"POST",headers:{"If-Match":`"${snapshot.catalog_revision}"`},body:JSON.stringify({schema_version:1,name:String(name||"").trim()})});showLineCandidateResult(`已创建禁用草稿 ${result.line?.name||result.line?.id}；补全并确认配置后再显式应用 Provider。`);await Promise.all([loadLineCatalog(),loadLineCandidates(),loadProviderConfig()]);if(result.line?.id){el("line-config-line").value=result.line.id;renderLineEditor();el("line-config-form").scrollIntoView({behavior:"smooth",block:"start"})}}catch(error){showLineCandidateResult(`创建失败：${lineCandidateError(error)}`,true);if(error.status===409||error.status===412)await Promise.all([loadLineCatalog(),loadLineCandidates()])}finally{button.disabled=false}}
